import{d as c,C as t,o as m,c as u,j as a,a as s,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第四十一章","description":"从闻道的三种回应，到若反的言说，理解大道何以不以显耀成物。","frontmatter":{"title":"道德经第四十一章","description":"从闻道的三种回应，到若反的言说，理解大道何以不以显耀成物。","category":"guide","aliases":["道德经第四十一章","老子第四十一章","dao de jing chapter 41"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-41.md","filePath":"daoism/dao-de-jing/chapter-41.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-41.md"},_=c({...g,setup(p){const o=[{id:"responses-to-dao",label:"上士闻道",showLabel:!0,sentences:[["上",{text:"士",glossary:"shi"},"闻道，",{text:"勤",glossary:"qin"},"而行之；中",{text:"士",glossary:"shi"},"闻道，若存若亡；下",{text:"士",glossary:"shi"},"闻道，大笑之。不笑不足以为道。"]],note:["【白话】上等的行道之士听闻道，便勤勉地实践；中等者听闻，时而记取、时而忘失；下等者听闻，便大加嘲笑。如果毫不引起这样的嘲笑，也就不足以称为这里所说的道。","【王弼注择要】王弼在勤而行之下注「有志也」，把重点放在实际行道的志向。","【读法】若存若亡在此写对道的持守不定，不沿用前章亡的身没语境。不笑不足以为道承接下士的反应，提示道与惯常尺度的冲突，不能倒过来把遭到嘲笑当作观点正确的证明。"]},{id:"brightness-and-levelness",label:"明道若昧",showLabel:!0,sentences:[["故",{text:"建言",glossary:"jianyan"},"有之：明道若",{text:"昧",glossary:"mei"},"，进道若退，",{text:"夷",glossary:"yi"},"道若",{text:"纇",glossary:"lei"},"，"]],note:["【白话】所以，立下的言说中有这样的话：明达之道看似昏暗，向前的道看似后退，平坦的道看似崎岖不平。","【王弼注择要】「建犹立也。」明道的注是「光而不耀」；夷道的注说「因物之性，不执平以割物」，即不拿一个僵硬的平齐标准裁割万物。","【读法】纇本有丝结、疵累之意，此处取看似不平之貌。进道若退可连第七章后其身而身先理解；这些若字不是倡导故意昏暗、退缩或制造障碍。"]},{id:"virtue-without-display",label:"上德若谷",showLabel:!0,sentences:[[{text:"上德",glossary:"shangde"},"若谷，",{text:"大白",glossary:"dabai"},"若辱，广德若不足，"]],note:["【白话】上等的德如空谷般不自满；极其洁白反而看似蒙垢；广大的德看似仍有不足。它们都不靠把自己呈现为满、白、大来显耀。","【王弼注择要】上德的注是「不德其德，无所怀也」；广德的注说「广德不盈，廓然无形，不可满也」，以不自据其德、不以有限形态自满说明。","【读法】本站保留大白，所据电子录文作太白，古注又作大白。本段以洁白与蒙垢作对照，不把受辱本身当作德，也不主张取消现实中的是非判断。"]},{id:"established-and-authentic",label:"建德若偷",showLabel:!0,sentences:[["建德若",{text:"偷",glossary:"tou"},"，",{text:"质真",glossary:"zhizhen"},"若",{text:"渝",glossary:"yu"},"，"]],note:["【白话】确立的德看似怠缓不作为，质朴真实的样子看似有所改变。这里说的是不刻意树立、夸示自己，因此可能不合人们期待的外观。","【王弼注择要】建德的注说「因物自然，不立不施」；质真的注说「质真者不矜其真」，都把若偷、若渝连到不自我标榜。","【读法】偷在此暂取怠缓之貌，不作偷盗；所据录文的偷匹字样难明，不据此强定字形。渝为改变，看似有变不等于真伪无别。"]},{id:"great-square-and-vessel",label:"大方无隅",showLabel:!0,sentences:[["大方无",{text:"隅",glossary:"yu-corner"},"，大器晚成，"]],note:["【白话】至大的方正不以棱角割伤事物，足以成就广大功用的器，其成就并非急速可见。这里将方与器从固定边界和眼前成效中展开。","【王弼注择要】大方的注为「方而不割，故无隅也」；大器下注以「大器成天下」说其成用的广大，并以「故必晚成也」收束。","【读法】隅为角。王注大器句中间录文有不持全别等难读字样，本页只节引可明确核对的两处；晚成不等于承诺每个人在晚年都会成功。"]},{id:"sound-and-image",label:"大音希声",showLabel:!0,sentences:[["大音",{text:"希",glossary:"xi"},"声，",{text:"大象",glossary:"daxiang"},"无形，"]],note:["【白话】至大的音不落实为可听见的某一种声音，至大的象不局限为可见的某一个形状。依王弼，它们之大在能统摄，而非声音更响、体积更大。","【王弼注择要】大音下注引「听之不闻名曰希」，并说「分则不能统众」；大象下注说「有形则有分」，说明具体声形各有所限。","【读法】希在此沿第十四章听而不闻之义，与第四十三章天下希及之的稀少义分开；无形不表示万物没有形状，而是道不被其中一形穷尽。"]},{id:"hidden-and-nameless",label:"道隐无名",showLabel:!0,sentences:[["道隐",{text:"无名",glossary:"wuming"},"。"]],note:["【白话】道隐而不显，也不能以固定名称限定。万物由它成就，却看不到一个可单独指认、用名字框定的造作形迹。","【王弼注择要】「物以之成而不见其成形，故隐而无名也。」注将隐、无名与成物而不显其形相连。","【读法】本句收拢前面大音、大象的无定形，并非把道说成只有少数人掌握的秘密。"]},{id:"support-and-completion",label:"善贷且成",showLabel:!0,sentences:[["夫唯道，善",{text:"贷",glossary:"dai"},"且成。"]],note:["【白话】唯有道，善于给予万物资助，并使它们各自成就。这样的给予不只是补一时的缺乏，也不靠强加统一模样来完成事物。","【王弼注择要】「贷之非唯供其乏而已」；又说「成之不加机匠之裁」，以不作刻意裁制说明善成。","【读法】贷取施与、资助义，不是现代银行借贷。结尾将全章看似反常的言说落回成物，不止于赞赏难懂与反直觉。"]}],r=[{id:"shi",term:"士",sense:1},{id:"qin",term:"勤",sense:2},{id:"jianyan",term:"建言",sense:1},{id:"mei",term:"昧",sense:1},{id:"yi",term:"夷",sense:2},{id:"lei",term:"纇",sense:1},{id:"shangde",term:"上德",sense:1},{id:"dabai",term:"大白",sense:1},{id:"tou",term:"偷",sense:1},{id:"zhizhen",term:"质真",sense:1},{id:"yu",term:"渝",sense:1},{id:"yu-corner",term:"隅",sense:1},{id:"xi",term:"希",sense:1},{id:"daxiang",term:"大象",sense:1},{id:"wuming",term:"无名",sense:2},{id:"dai",term:"贷",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十一章",tabindex:"-1"},[s("道德经第四十一章 "),a("a",{class:"header-anchor",href:"#道德经第四十一章","aria-label":'Permalink to "道德经第四十一章"'},"​")],-1)),n(i,{title:"为什么明道若昧，大器晚成",summary:"本章先写闻道者的三种回应，再用一连串若字，松动以显耀、速成和固定形状衡量道的习惯。王弼以不耀、不割、因物自然贯通这些看似相反的说法，最后收于善贷且成。",points:[{label:"先读",text:"勤行、犹疑与大笑写接受的不同，不能凭受嘲笑便自证得道。"},{label:"再辨",text:"若字说外观与成用的落差，不等于混淆明暗、真伪与是非。"},{label:"后看",text:"大音、大象不以一声一形为限，结尾再看道如何资助并成全万物。"}],hint:"纇读 lèi，渝、隅读 yú，贷读 dài；夷在此取平坦义，勤取勤勉义，与前章旧义分开。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:o,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"明道若昧，进道若退，夷道若纇，",tone:"不以显耀与齐平为度",guide:"循光而不耀、因物之性来读，不为反常本身喝彩。"},{text:"大方无隅，大器晚成，",tone:"从一角一器走向成物",guide:"方不割物，器以成天下为大；晚成不能读成成功保证。"},{text:"夫唯道，善贷且成。",tone:"以成物收束",guide:"给予并成全各物，而不强加同一形态，贯通前面所有若字。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章为何先写三种闻道者" tabindex="-1">象：这一章为何先写三种闻道者？ <a class="header-anchor" href="#象-这一章为何先写三种闻道者" aria-label="Permalink to &quot;象：这一章为何先写三种闻道者？&quot;">​</a></h3><p>三种回应让读者先看见，听闻相同的道，可能走向实践、犹疑或嘲笑。后面的若字列举它为何不合惯常期待；重点在如何行道，而非给自己贴上上士标签。</p><h3 id="理-若字是否把相反的东西都说成一样" tabindex="-1">理：若字是否把相反的东西都说成一样？ <a class="header-anchor" href="#理-若字是否把相反的东西都说成一样" aria-label="Permalink to &quot;理：若字是否把相反的东西都说成一样？&quot;">​</a></h3><p>若表示看起来如此，仍保留明与昧、进与退的区别。王弼把这些落差解释为不耀、不割、不矜：成物的作用，不必总以显赫、整齐和立即完成的外观出现。</p><h3 id="用-怎样借此反省判断事物的尺度" tabindex="-1">用：怎样借此反省判断事物的尺度？ <a class="header-anchor" href="#用-怎样借此反省判断事物的尺度" aria-label="Permalink to &quot;用：怎样借此反省判断事物的尺度？&quot;">​</a></h3><p>先区分看起来出色与实际帮助事物成就，再检查自己的判断有无证据。遭到嘲笑或进展缓慢都不能自证正确，勤而行之仍需要持续实践与检验。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>给看不见的成效一点观察时间。</strong> 教育、协作和制度的成效，常不能只看一时声量。可以观察它是否持续帮助具体的人与事，而不是把不显眼自动美化为高明。</p><p><strong>支持不必变成裁制。</strong> 提供资源、方法和反馈时，也给对方留下形成自己路径的余地。善贷且成提醒我们，帮助的结果应是事物更能成立，而非更像帮助者。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是在观察真实成效，还是只看整齐、迅速与显眼？哪些地方可以少一点自我显示，多一点帮助事物成就？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 005b–007a 核对；本站大白与录文太白的差异已在段释义说明。</li><li>勤、夷按本章另列勤勉、平坦义；希沿听而不闻义，不与天下希及之混用。</li><li>古注经注连排；偷匹及大器下注不持全别等难读处不擅改后作确定引文。若字的解释与本站现代类比均另行标识。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，005b–007a</a>。</p>',15))])}}});export{f as __pageData,_ as default};
